insert into wines (id, slug, name, type, grape_variety, vineyard_name, vineyard_description, grape_description, plot_size, fermentation, maceration, aging_vessel, barrel_size, aging_notes, experience_description, pairing_text, abv, serving_temp, image_url, featured, image_media_id, sort_order, altitude, training_system, cultivation_method, harvest_period, grape_yield, vineyard_parcels, unfiltered) values
  ('1', 'dogliani-superiore-coste-di-san-martino', 'Dogliani Superiore — Coste di San Martino', 'red', 'Dolcetto', 'Coste di San Martino, Dogliani', 'From the Coste di San Martino vineyard in Dogliani (CN), Piemonte — the heartland of Dolcetto, and the only place in Italy where this grape earns DOCG Superiore status. [Placeholder — Roberto to add detail on the plot: exposure, altitude, soil.]', '100% Dolcetto, vinified to the stricter Dogliani Superiore standard, which requires lower yields and a minimum period of ageing before release — a world apart from simple, early-drinking Dolcetto.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm maceration length]', 'barrel', '500L (tonneau)', '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to confirm tasting notes.] Deep ruby in the glass, with dark plum, violet and the characteristic bitter-almond note on the finish that''s the signature of great Dolcetto di Dogliani. Fuller and more structured than most Dolcetto thanks to the Superiore ageing requirement.', 'Classic Piemontese fare — tajarin with ragù, braised meats, or hard mountain cheeses. Serve at 16–18°C.', '14%', '16–18°C', '/wines/dogliani-superiore-coste-di-san-martino.jpg', true, 'media-1', 10, null, null, null, null, null, null, null),
  ('2', 'dogliani-superiore-vescu', 'Dogliani Superiore — Vescu', 'red', 'Dolcetto', 'Vescu, Dogliani', 'From the Vescu vineyard in Dogliani — a separate cru from Coste di San Martino, giving Roberto two distinct expressions of Dogliani Superiore from the same estate. [Placeholder — Roberto to add what makes Vescu different: soil, exposure, age of vines.]', '100% Dolcetto, vinified to Dogliani Superiore DOCG standard.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm maceration length]', 'barrel', '500L (tonneau)', '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to add tasting notes for Vescu specifically, and how it compares to Coste di San Martino.]', '[Placeholder — pairing suggestions to confirm.] Serve at 16–18°C.', '14%', '16–18°C', '/wines/dogliani-superiore-vescu.jpg', true, 'media-2', 20, null, null, null, null, null, null, null),
  ('3', 'dogliani-pianezzo', 'Dogliani — Pianezzo', 'red', 'Dolcetto', 'Pianezzo MGA, Dogliani', 'The Pianezzo MGA is part of the Dogliani DOCG, a high-altitude ridge at 420–600 meters above sea level, renowned for its fresh, deeply-fruited 100% Dolcetto wines. These chalky calcareous-clay soils are the continuation of the Serravallian ridge that extends south through the hills of Serralunga in Barolo, culminating in the hill of San Martino, below which sits Casa Valletti.', 'Dolcetto 100%, from 3 different vineyards blended after malolactic fermentation.', '[Placeholder — total plot size in hectares not on Roberto''s sheet; yield confirmed at 7 tons/ha across the 3 blended parcels]', 'Traditional method, fermentation of the grapes in contact with the skins, without added yeasts, for around 6–8 days in stainless steel tanks at 28°C (82.4°F).', '6–8 days on the skins, together with fermentation.', 'steel', null, '8 months in stainless steel tanks, then 6 months in bottle.', '[Placeholder — Roberto to confirm tasting notes.]', '[Placeholder — pairing suggestions to confirm.]', '[Placeholder — confirm alcohol %]', '[Placeholder — confirm serving temperature]', '/wines/dogliani-pianezzo.jpg', true, 'media-3', 30, '500 m s.l.m. (1640 ft)', 'Espalier with Guyot pruning system', 'No systemic products are used and weed control is carried out mechanically.', 'Mid-September', '7 tons per hectare (2.8 tons per acre)', '[{"exposure":"West","soil":"Formazione di Lequio (Serravalliano), clayey marl with silt, brown colour","averageAge":"15 years old"},{"exposure":"East","soil":"Formazione di Lequio (Serravalliano), clayey marl with a part of silt and limestone, white colour","averageAge":"30 years old"},{"exposure":"South-East","soil":"Formazione di Lequio (Serravalliano), lime marl with a small part of sand, white colour","averageAge":"25 years old"}]'::jsonb, true),
  ('4', 'langhe-nebbiolo', 'Langhe Nebbiolo', 'red', 'Nebbiolo', '[Placeholder — confirm vineyard/plot name]', '[Placeholder — Roberto to describe the Nebbiolo vineyard: location, exposure, why it sits under Langhe DOC rather than Barolo/Barbaresco.]', '100% Nebbiolo, Piemonte''s most prized red grape.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm maceration length]', 'barrel', '225L (barrique)', '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to add tasting notes: expect the classic Nebbiolo profile of red fruit, rose and firm tannin, in a more approachable Langhe style.]', '[Placeholder — pairing suggestions to confirm.] Serve at 16–18°C.', '14%', '16–18°C', '/wines/langhe-nebbiolo.jpg', true, 'media-4', 40, null, null, null, null, null, null, null),
  ('5', 'langhe-barbera', 'Langhe Barbera', 'red', 'Barbera', '[Placeholder — confirm vineyard/plot name]', '[Placeholder — Roberto to describe the vineyard this Barbera comes from.]', '100% Barbera, known for its bright acidity and dark-fruit character.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm maceration length]', 'steel', null, '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to add tasting notes.]', '[Placeholder — pairing suggestions to confirm.] Serve at 16°C.', '13.5%', '16°C', '/wines/langhe-barbera.jpg', false, 'media-5', 50, null, null, null, null, null, null, null),
  ('6', 'langhe-barbera-lurenzin', 'Langhe Barbera — Lurenzin', 'red', 'Barbera', 'Lurenzin', 'A single-vineyard Barbera from the Lurenzin plot — the estate''s more structured take on Barbera, distinct from the standard Langhe Barbera bottling. [Placeholder — Roberto to add detail on the plot and how it differs.]', '100% Barbera, vinified from the Lurenzin cru.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm maceration length]', 'barrel', '350L', '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to add tasting notes specific to Lurenzin.]', '[Placeholder — pairing suggestions to confirm.] Serve at 16–17°C.', '14%', '16–17°C', '/wines/langhe-barbera-lurenzin.jpg', false, 'media-6', 60, null, null, null, null, null, null, null),
  ('7', 'langhe-bianco', 'Langhe Bianco', 'white', 'Timorasso', '[Placeholder — confirm vineyard/plot name]', '[Placeholder — Roberto to describe the Timorasso vineyard: location, exposure, soil.]', '100% Timorasso — a native Piemontese white grape prized for its ability to age, developing rich texture and honeyed, mineral notes over time.', '[Placeholder — confirm plot size in hectares]', '[Placeholder — Roberto to confirm: steel tank, controlled temperature]', '[Placeholder — Roberto to confirm — typically minimal/no skin contact for this white]', 'steel', null, '[Placeholder — Roberto to confirm ageing period before release]', '[Placeholder — Roberto to add tasting notes.]', '[Placeholder — pairing suggestions to confirm.] Serve chilled at 8–10°C.', '13%', '8–10°C', '/wines/langhe-bianco.jpg', false, 'media-7', 70, null, null, null, null, null, null, null)
